import{_ as e,o,c as r,a2 as n}from"./chunks/framework.Desnpdez.js";const m=JSON.parse('{"title":"Connection transports (technical)","description":"","frontmatter":{},"headers":[],"relativePath":"reference/server-transports.md","filePath":"reference/server-transports.md"}'),a={name:"reference/server-transports.md"};function s(d,t,i,c,l,h){return o(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="connection-transports-technical" tabindex="-1">Connection transports (technical) <a class="header-anchor" href="#connection-transports-technical" aria-label="Permalink to &quot;Connection transports (technical)&quot;">​</a></h1><p>MindBehindAI supports three ways a <strong>connection</strong> can talk to its tool. You normally pick the right type when you <strong>add a connection</strong> or when a <strong>Library</strong> preset fills it in for you.</p><table tabindex="0"><thead><tr><th>Transport</th><th>In the app</th><th>Typical use</th></tr></thead><tbody><tr><td><strong>Stdio (local process)</strong></td><td>Command + arguments run on your Mac</td><td><code>npx …</code>, local Python tools, many presets</td></tr><tr><td><strong>SSE (HTTP)</strong></td><td>Long-lived HTTP stream to a URL</td><td>Less common; some hosted servers</td></tr><tr><td><strong>Streamable HTTP</strong></td><td>HTTP MCP endpoint</td><td>Telekom Telecontext and similar remote gateways</td></tr></tbody></table><p><strong>You do not need to memorise this.</strong> If a vendor gives you a URL, they will say whether it is SSE or streamable HTTP. If they give you a command to paste, it is almost always <strong>Stdio</strong>.</p><p>The assistant bridge runs these connections through a local <a href="https://github.com/open-webui/mcpo" target="_blank" rel="noreferrer"><strong>mcpo</strong></a> process; <strong>stdio</strong> children inherit a bundled toolchain (<code>node</code>, <code>npx</code>, <code>uv</code>/<code>uvx</code>, <code>python3</code>, …) so a separate Homebrew install is usually unnecessary.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><strong><a href="./host-parity.html">Compared to other MCP hosts</a></strong> — how this app differs from IDE-embedded MCP.</li><li><strong><a href="./../everyday/connections.html">Connections</a></strong> — where you add or edit connections.</li></ul>',7)])])}const g=e(a,[["render",s]]);export{m as __pageData,g as default};
